import threading
import hashlib
import time
import os
from collections import defaultdict


class SessionStore:
    """Thread-safe session store with cryptographic token validation."""

    def __init__(self):
        self._sessions = {}
        self._lock = threading.Lock()
        self._rate_limits = defaultdict(list)
        self._max_attempts = 5
        self._window = 60

    def create_session(self, user_id, permissions):
        """Create a new session with a secure random token."""
        token = hashlib.sha256(os.urandom(32)).hexdigest()
        with self._lock:
            self._sessions[token] = {
                'user_id': user_id,
                'permissions': frozenset(permissions),
                'created_at': time.time(),
                'last_access': time.time()
            }
        return token

    def get_session(self, token):
        """Retrieve session data (returns a copy for safety)."""
        with self._lock:
            session = self._sessions.get(token)
            if session:
                session['last_access'] = time.time()
                return {
                    'user_id': session['user_id'],
                    'permissions': set(session['permissions']),
                    'created_at': session['created_at'],
                    'last_access': session['last_access']
                }
            return None

    def revoke_session(self, token):
        """Revoke a session token."""
        with self._lock:
            return self._sessions.pop(token, None) is not None

    def update_permissions(self, token, new_permissions):
        """Atomically update session permissions."""
        with self._lock:
            if token in self._sessions:
                self._sessions[token]['permissions'] = frozenset(new_permissions)
                return True
            return False


class PermissionCache:
    """Caches resolved permissions to avoid repeated DB lookups."""

    def __init__(self):
        self._cache = {}
        self._lock = threading.Lock()
        self._ttl = 300  # 5 minute TTL

    def get_permissions(self, user_id):
        with self._lock:
            entry = self._cache.get(user_id)
            if entry and (time.time() - entry['ts']) < self._ttl:
                return set(entry['perms'])
            return None

    def set_permissions(self, user_id, perms):
        with self._lock:
            self._cache[user_id] = {'perms': frozenset(perms), 'ts': time.time()}

    def invalidate(self, user_id):
        with self._lock:
            self._cache.pop(user_id, None)


class AccessController:
    """Controls access to resources based on session permissions.

    Uses a two-level permission model:
    1. Session-level permissions (set at login)
    2. Cached effective permissions (resolved from roles)
    """

    def __init__(self, session_store, permission_cache):
        self._session_store = session_store
        self._permission_cache = permission_cache
        self._resource_locks = {}
        self._resource_lock_guard = threading.Lock()
        self._audit_log = []
        self._audit_lock = threading.Lock()

    def _get_resource_lock(self, resource_id):
        """Get or create a per-resource lock for fine-grained locking."""
        with self._resource_lock_guard:
            if resource_id not in self._resource_locks:
                self._resource_locks[resource_id] = threading.Lock()
            return self._resource_locks[resource_id]

    def _audit(self, action, user_id, resource_id, result):
        with self._audit_lock:
            self._audit_log.append({
                'time': time.time(),
                'action': action,
                'user_id': user_id,
                'resource_id': resource_id,
                'result': result
            })

    def check_access(self, token, resource_id, required_permission):
        """Check if a session token grants access to a resource.

        Thread-safe: uses per-resource locking to prevent race conditions
        during permission evaluation.
        """
        # Validate session
        session = self._session_store.get_session(token)
        if not session:
            return {'granted': False, 'reason': 'invalid_session'}

        user_id = session['user_id']

        # Get the resource lock for atomic permission checking
        resource_lock = self._get_resource_lock(resource_id)

        with resource_lock:
            # Check cached effective permissions first
            effective_perms = self._permission_cache.get_permissions(user_id)

            if effective_perms is None:
                # Cache miss - resolve from session permissions
                effective_perms = self._resolve_permissions(session['permissions'])
                self._permission_cache.set_permissions(user_id, effective_perms)

            granted = required_permission in effective_perms

        self._audit('check_access', user_id, resource_id, granted)
        return {'granted': granted, 'reason': 'ok' if granted else 'insufficient_permissions'}

    def _resolve_permissions(self, base_permissions):
        """Resolve effective permissions from base permissions.
        Expands role-based permissions into concrete permissions.
        """
        resolved = set(base_permissions)
        role_expansions = {
            'admin': {'read', 'write', 'delete', 'manage_users'},
            'editor': {'read', 'write'},
            'viewer': {'read'}
        }
        for perm in list(base_permissions):
            if perm in role_expansions:
                resolved.update(role_expansions[perm])
        return resolved

    def elevate_session(self, admin_token, target_token, new_permissions):
        """Allow an admin to elevate another session's permissions.

        This is the critical security operation - must be atomic.
        """
        # Verify admin has manage_users permission
        admin_session = self._session_store.get_session(admin_token)
        if not admin_session:
            return {'success': False, 'error': 'invalid_admin_session'}

        admin_perms = self._resolve_permissions(admin_session['permissions'])
        if 'manage_users' not in admin_perms:
            return {'success': False, 'error': 'not_authorized'}

        # Elevate the target session
        target_session = self._session_store.get_session(target_token)
        if not target_session:
            return {'success': False, 'error': 'invalid_target_session'}

        target_user = target_session['user_id']

        # Update session permissions through the proper API
        updated = self._session_store.update_permissions(target_token, new_permissions)
        if not updated:
            return {'success': False, 'error': 'session_expired'}

        # Invalidate permission cache so new perms take effect
        self._permission_cache.invalidate(target_user)

        self._audit('elevate', admin_session['user_id'], target_user, True)
        return {'success': True}

    def revoke_and_check(self, token_to_revoke, check_token, resource_id, permission):
        """Atomically revoke a session and check if another token still has access.

        Used during security incidents to revoke compromised sessions
        while verifying remaining sessions are still valid.
        """
        # Phase 1: Revoke the compromised session
        revoked = self._session_store.revoke_session(token_to_revoke)

        # Phase 2: Verify the check_token still works
        result = self.check_access(check_token, resource_id, permission)
        result['revoked'] = revoked
        return result


class PrivilegeEscalationGuard:
    """Prevents privilege escalation by validating permission transitions."""

    def __init__(self, access_controller):
        self._controller = access_controller
        self._escalation_lock = threading.Lock()
        self._pending_elevations = {}

    def request_elevation(self, admin_token, target_token, requested_perms):
        """Request a privilege elevation with validation."""
        with self._escalation_lock:
            # Validate the admin can grant these specific permissions
            admin_session = self._controller._session_store.get_session(admin_token)
            if not admin_session:
                return {'approved': False, 'error': 'invalid_admin'}

            admin_effective = self._controller._resolve_permissions(admin_session['permissions'])

            # Admin can only grant permissions they themselves have
            requested_set = set(requested_perms)
            if not requested_set.issubset(admin_effective):
                return {'approved': False, 'error': 'cannot_grant_unowned_permissions'}

            # Store pending elevation
            elevation_id = hashlib.sha256(os.urandom(16)).hexdigest()[:16]
            self._pending_elevations[elevation_id] = {
                'admin_token': admin_token,
                'target_token': target_token,
                'permissions': list(requested_perms),
                'requested_at': time.time()
            }
            return {'approved': True, 'elevation_id': elevation_id}

    def execute_elevation(self, elevation_id):
        """Execute a previously approved elevation."""
        with self._escalation_lock:
            elevation = self._pending_elevations.pop(elevation_id, None)
            if not elevation:
                return {'success': False, 'error': 'invalid_elevation_id'}

            # Check if elevation request is still fresh (5 minute window)
            if time.time() - elevation['requested_at'] > 300:
                return {'success': False, 'error': 'elevation_expired'}

        # Execute the elevation (outside escalation lock to avoid deadlock)
        return self._controller.elevate_session(
            elevation['admin_token'],
            elevation['target_token'],
            elevation['permissions']
        )


def run_security_test():
    """Integration test demonstrating the access control system."""
    store = SessionStore()
    cache = PermissionCache()
    controller = AccessController(store, cache)
    guard = PrivilegeEscalationGuard(controller)

    # Create sessions
    admin_token = store.create_session('admin_user', ['admin'])
    user_token = store.create_session('regular_user', ['viewer'])

    # Verify initial access
    result = controller.check_access(user_token, 'secret_doc', 'write')
    assert not result['granted'], "User should not have write access"

    result = controller.check_access(user_token, 'secret_doc', 'read')
    assert result['granted'], "User should have read access"

    # Test elevation through guard
    elevation = guard.request_elevation(admin_token, user_token, ['editor'])
    assert elevation['approved']

    exec_result = guard.execute_elevation(elevation['elevation_id'])
    assert exec_result['success']

    # After elevation, user should have write access
    result = controller.check_access(user_token, 'secret_doc', 'write')
    assert result['granted'], "User should now have write access after elevation"

    print("All security tests passed.")


if __name__ == '__main__':
    run_security_test()
